・ひっかけ3：「電気工事士法は電気用品の表示について定めている」→×。表示は電気用品安全法
・ひっかけ4：資格を「国家資格ではなく都道府県知事の免許」と書く選択肢。免状の交付は都道府県知事が行うので、この記述自体は正しい○
・条文の細かい数字より、どの法律の話かを一瞬で切り分ける訓練が得点に直結する

