　いきなり条文を読むと混乱するので、まず「受電電圧の高さ」という一本の物差しで並べてみるとよい。家庭やコンビニのように電力会社から低圧（100Vや200V）で受電する建物が一般用電気工作物、工場やビルのように高圧（6600Vなど）で受電する建物が自家用電気工作物である。
