　仕分けの原則はきわめて単純で、電力会社から低圧（600V以下）で受電していれば一般用、それ以外は自家用である。家庭、アパート、コンビニ、小さな町工場の多くは一般用。高圧受電のスーパー、学校、病院、大きな工場は自家用となる。
