・条件3：構内に600Vを超える電気工作物（高圧の電線路など）がないこと★
・さらに、同一構内に設置された小規模発電設備は一般用に含めてよい
・逆にいえば、構内に高圧の受変電設備があれば、たとえ低圧で使う部分があっても、その建物全体が自家用になる★

