━━━━━━━━━━━━━━━━━━━━━━
・太陽電池発電設備：出力50kW未満★
・風力発電設備：出力20kW未満★
・水力発電設備：出力20kW未満（ダムを伴わないもの）
・内燃力発電設備：出力10kW未満★
・燃料電池発電設備：出力10kW未満（固体高分子形などで一定の条件を満たすもの）
・スターリングエンジン発電設備：出力10kW未満
・これらは電圧600V以下で発電するものに限られる
