・典型例は高圧（6600V）で受電する工場・ビル・商業施設
・小規模発電設備の出力を超える発電設備を持つ場所も自家用になる
・電気工事士法上は、このうち最大電力500kW未満の需要設備が第一種電気工事士の対象

【図解】一般用と自家用の見分け方
