・ひっかけ3：「高圧受電で最大電力300kWの需要設備」→×。高圧受電なので自家用
・ひっかけ4：「低圧受電で出力10kWの内燃力発電設備を有するもの」→×。内燃力は10kW未満なので、ちょうど10kWは自家用★
