・つまり区分が変わると、工事の資格・保安体制・調査の主体がまとめて切り替わる★
・小規模発電設備の出力がわずかに基準を超えただけで、この重い体制へ移行する。だから数字の暗記が実務上も重要になる

★ここだけ暗記
・一般用＝低圧600V以下で受電し、構内に高圧設備がないこと
・太陽電池50kW未満、風力20kW未満、水力20kW未満、内燃力と燃料電池10kW未満。すべて未満
・複数設備の合計は50kW未満
