　もし電気に関わるあらゆる作業に免状が必要だとしたら、切れた電球を交換するのにも電気工事士を呼ばなければならなくなる。それでは社会が回らない。そこで電気工事士法施行令第1条は、危険性が低い一定の工事を「軽微な工事」として、そもそも法律上の電気工事から除外している。
　ここで重要なのは、軽微な工事は「電気工事だが例外的に無資格でよい」のではなく「そもそも電気工事に当たらない」という建て付けになっている点である。したがって軽微な工事に該当すれば、資格の有無を問う余地がない。
　試験では6項目のリストがほぼそのまま問われる。数字（600V、36V）と対象物をセットで暗記するのが最短ルートである★

