・項目3：電圧600V以下で使用する電力量計、電流制限器、またはヒューズを取り付け、または取り外す工事★
・項目4：電鈴、インターホーン、火災感知器、豆電球その他これらに類する施設に使用する小型変圧器（二次電圧が36V以下のものに限る）の二次側の配線工事★
