・600V以下：接続器への接続、電気機器や蓄電池の端子へのねじ止め、電力量計・電流制限器・ヒューズの取付け取外し
・36V以下：小型変圧器の二次側配線（電鈴、インターホーン、火災感知器、豆電球）★
・数字がないもの：電線を支持する柱や腕木、地中電線用の暗渠や管
・つまり数字が出てくるのは4項目だけ。600Vが3つ、36Vが1つと覚える★

