・ひっかけ4：「地中電線用の管の中に電線を通す工事」→電気工事。管を埋めるだけが軽微
・ひっかけ5：「配電盤を造営材に取り付ける工事」→電気工事。軽微ではない

★ここだけ暗記
・軽微な工事は6項目。600Vが3つ、36Vが1つ、数字なしが2つ
・電気機器の端子へのねじ止めは軽微だが、配線器具は除外される
・36Vは小型変圧器の二次電圧。二次側の配線だけが軽微
