　試験に合格しても、それだけでは電気工事士になれない。都道府県知事に申請して免状の交付を受けて、はじめて電気工事士である。免状は運転免許証のようなカード状の証明書で、氏名、生年月日、交付年月日、交付番号、交付した知事名が記載されている。
　実務では引っ越しや結婚で記載事項が変わることがあり、また紛失や汚損もある。そこで交付・書換え・再交付という3つの手続が用意されている。試験では「どこに申請するか」が繰り返し問われる。ここだけを正確に押さえればよい★

