　義務は大きく4つある。無資格者に工事をさせない・自分の範囲を超えない（従事制限）、作業中は免状を携帯する（携帯義務）、技術基準に適合させる（適合義務）、求められたら報告する（報告義務）である。これに第一種の定期講習義務を加えて5つと数えることもある★

