・ひっかけ3：「電気工事士が電力量計を取り付けた」→軽微な工事なので違反ではない○
・ひっかけ4：「免状の返納を命ぜられた者が、翌月に免状の交付を申請した」→1年を経過していないので交付を受けられない×★

