　電気工事士法が「人」を規制する法律だとすれば、電気事業法は「設備と事業」を規制する基本法である。発電所から変電所、送電線、配電線、そして各家庭の分電盤まで、電気に関わるあらゆる設備を「電気工作物」という言葉でひとくくりにし、その工事・維持・運用を規制している。
　第二種電気工事士の試験では、電気事業法そのものより、そこから導かれる「一般用電気工作物の範囲」や「電圧の種別」が問われることが多い。しかし土台となる分類を理解しておかないと、それらの規定が宙に浮いてしまう。まずは電気工作物の分類の全体像を頭に入れよう★

