・したがって最終的には、電気事業用・自家用・一般用の3つになる
・電気事業用は電力会社の発電所、変電所、送電線、配電線など
・自家用は高圧受電の工場やビル、大規模な自家発電設備を持つ場所
・一般用は低圧受電の住宅や小規模店舗

