　電気事業法は、これらの者に対して一般用電気工作物を調査する義務を課している。訪問して絶縁抵抗を測り、分電盤を見て、技術基準に適合していなければ所有者に通知する。これが一般用に対する保安の仕組みである。試験では調査の頻度と、不適合時の措置が問われる★

