・ひっかけ3：「調査の結果不適合であれば、調査機関が修理しなければならない」→×。通知するだけ★
・ひっかけ4：「調査は変更工事が完成したときには不要である」→×。その都度必要
・ひっかけ5：「調査を拒まれても必ず調査しなければならない」→×。正当な理由があればしなくてよい

