・配電線には電圧降下があり、変圧器から遠い需要家ほど電圧が下がる
・そこで送り出し側を少し高めに設定し、平均して100V付近になるように調整している
・その結果、中心値がわずかに高い101Vとなっている
・また、電気機器は電圧が低すぎると性能が落ち、高すぎると寿命が縮む。上下に幅を持たせつつ中心を100Vよりやや上に置くのは合理的である★

