・電圧降下が大きい場合の対策は、電線を太くする、配電用変圧器のタップを調整する、自動電圧調整器を設置するなどである★
・屋内側では、幹線や分岐回路の電圧降下を標準電圧の2パーセント以内に抑えるという内線規程の目安がある

