　どれほど腕のよい電気工事士が丁寧に施工しても、使った電線やコンセントの品質が悪ければ事故は防げない。被覆が薄い電線、接触部の弱いコンセント、耐熱性の足りない配線器具。こうした粗悪品が市場に出回れば、施工の良し悪しにかかわらず火災が起きる。
　そこで国は、電気工事に使う材料や家庭用の電気製品そのものを「電気用品」と定義し、製造・輸入・販売の各段階で規制をかけた。これが電気用品安全法である。略して電安法と呼ばれる。
　第二種電気工事士の試験では、毎年1問程度、特定電気用品かどうかの判別か、表示記号の意味が問われる。判別の基準と記号の形を確実に覚えておきたい★

━━━━━━━━━━━━━━━━━━━━━━
