・電気用品の製造、輸入、販売等を規制するとともに、電気用品の安全性の確保につき民間事業者の自主的な活動を促進することにより、電気用品による危険および障害の発生を防止すること★
・キーワードは「製造、輸入、販売等の規制」「民間事業者の自主的な活動」「危険および障害の発生の防止」★
・電気工事士法の目的（電気工事の欠陥による災害の防止）とは明確に違う
・電気事業法の目的（公共の安全の確保と環境の保全）とも違う
・3法の目的を並べて問う出題があるので、キーワードで区別できるようにしておく
・「自主的な活動を促進する」という表現は、国が全部検査するのではなく事業者の自己確認を基本とする制度設計を表している★

