━━━━━━━━━━━━━━━━━━━━━━
・小形単相変圧器：定格容量500VA以下のもの（ネオン変圧器を含む）★
・電熱器具：電気温水器、観賞魚用ヒーター、電気便座など、定格消費電力10kW以下のもの★
・電動力応用機械器具：ポンプ、電気マッサージ器、自動販売機など★
・電気ポンプは特定電気用品だが、家庭用の電気冷蔵庫は特定電気用品以外である
・携帯発電機：定格電圧30V以上300V以下のもの★
・リチウムイオン蓄電池：一定の条件を満たすもの

