・ひし形が難しい場合は、代替として文字表記が認められている。すなわち丸括弧付きの表記や、特定電気用品である旨を示す文字
・あわせて、届出事業者の氏名または名称（登録商標も可）を表示する★
・さらに、適合性検査を行った登録検査機関の名称または略称を表示する★
・この「検査機関の名称」が入るのは特定電気用品だけである。丸形にはない★
・電線類のように表面積が小さいものは、外装に一定間隔で繰り返し印字される

━━━━━━━━━━━━━━━━━━━━━━
