・あわせて、届出事業者の氏名または名称を表示する
・登録検査機関の名称は不要である★（自主検査だから）
・その他、定格電圧、定格電流、定格消費電力など、品目ごとに定められた事項を表示する
・つまり丸形は「事業者が自分で確認しました」という意思表示である
・ひし形は「第三者機関が確認しました」という意思表示である

