・電気工事の副資材（サドル、ステープル、絶縁テープ、リングスリーブ、差込形コネクタ）は電気用品ではない★
・つまりリングスリーブにPSEマークは付かない。ここは意外に思われるが重要なポイントである
・電線接続材料は電気用品ではなく、日本産業規格などで品質が担保されている

