　電技解釈は、接地工事をA種、B種、C種、D種の4つに分類し、それぞれ接地抵抗値と接地線の太さを定めている。第二種電気工事士の試験では、主にC種とD種が問われるが、4種類の全体像を押さえておくと理解が深まる★

