　引込線取付点から先、電力量計を経て分電盤の主開閉器までの配線を引込口配線という。この区間は電力会社の設備と需要家の設備の境目にあたり、高さや太さに細かい規定がある。試験では引込線の高さの数値が繰り返し問われる★

━━━━━━━━━━━━━━━━━━━━━━
