・ひっかけ2：「メタルラスを切り開き、絶縁管を挿入して電線を貫通させた」→○正しい★
・ひっかけ3：「メタルラスと金属管を電気的に完全に接続し、D種接地工事を施した」→×。接続してはならない★
・ひっかけ4：「メタルラス張りへの金属管の取付けは無資格者でもできる」→×。電気工事士の作業★
・ひっかけ5：「金属板張りの造営材には規定が適用されない」→×。適用される

★ここだけ暗記
・メタルラス張り、ワイヤラス張り、金属板張りが対象
・電線や金属管を金属部分と電気的に接続してはならない
・貫通部はメタルラスを切り開き、絶縁管または絶縁テープで絶縁
