        body: `▼ゼロから：建物の構造で工事方法が変わる
　同じ屋内配線でも、木造の建物と鉄筋コンクリート造の建物では、使える工事方法が違う場面がある。また、天井裏のように点検できるかどうかで制限が変わる場所もある。
　電技解釈は、施設場所を「展開した場所」「点検できる隠ぺい場所」「点検できない隠ぺい場所」に分け、さらに「乾燥した場所」「湿気の多い場所または水気のある場所」に分けて、それぞれ使える工事方法を定めている。ここを表として押さえるのが要点である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 施設場所の分類
━━━━━━━━━━━━━━━━━━━━━━
・展開した場所：点検できる、露出した場所。壁や天井の表面など★
・点検できる隠ぺい場所：点検口のある天井裏、床下、押入れの上部など★
・点検できない隠ぺい場所：壁の中、コンクリートの中、天井ふところなど★
・乾燥した場所：水気も湿気もない場所
・湿気の多い場所：水蒸気が充満する場所、水気のある場所は水を扱う場所★
・この2つの軸を組み合わせて、工事方法の可否が決まる

━━━━━━━━━━━━━━━━━━━━━━
🔑 どこでも施設できる3つの工事
━━━━━━━━━━━━━━━━━━━━━━
・ケーブル工事★
・金属管工事★
・合成樹脂管工事（CD管を除く）★
・この3つは、展開した場所でも隠ぺい場所でも、乾燥していても湿気があっても施設できる★
・つまり迷ったらこの3つは可、と覚えてよい
・第二種の試験では、この3つを軸に他の工事の制限を覚えるのが効率的である

━━━━━━━━━━━━━━━━━━━━━━
🔑 制限のある工事方法
━━━━━━━━━━━━━━━━━━━━━━
・がいし引き工事：展開した場所と点検できる隠ぺい場所のみ。点検できない隠ぺい場所は不可★
・金属線ぴ工事：展開した場所と点検できる隠ぺい場所で、乾燥した場所のみ★
・金属ダクト工事、バスダクト工事：展開した場所と点検できる隠ぺい場所で、乾燥した場所のみ★
・ライティングダクト工事：展開した場所と点検できる隠ぺい場所で、乾燥した場所のみ★
・平形保護層工事：点検できる隠ぺい場所で乾燥した場所のみ（床面に限る）★
・つまりダクト系と線ぴ系は「乾燥した場所」「点検できる」が条件になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 木造に特有の制限
━━━━━━━━━━━━━━━━━━━━━━
・屋側配線では、木造の造営物に金属管工事とバスダクト工事ができない★
・メタルラス張り、ワイヤラス張り、金属板張りの造営材では、電気的に接続しないよう施設する★
・木造でも屋内配線については、金属管工事もケーブル工事も施設できる○★
・つまり制限がかかるのは屋側であって、屋内ではない点に注意する★
・この区別を取り違えると、選択肢の判定を誤る
・実務では、木造住宅の屋内はVVFケーブルによるケーブル工事が圧倒的に多い

━━━━━━━━━━━━━━━━━━━━━━
🔑 使用電圧300V超の追加制限
━━━━━━━━━━━━━━━━━━━━━━
・使用電圧が300Vを超える低圧屋内配線では、施設できる工事方法が減る★
・金属線ぴ工事、ライティングダクト工事、平形保護層工事は施設できない×★
・がいし引き工事は乾燥した場所の展開した場所と点検できる隠ぺい場所に限られる
・金属管、金属ダクト、バスダクトなどの金属部分にはC種接地工事を施す★
・300V以下ならD種接地工事でよい★
・つまり電圧が上がると、工事方法が減り、接地が厳しくなる

【図解】施設場所と工事方法
　工事方法｜点検できない隠ぺい場所｜湿気の多い場所
　ケーブル工事｜○可★｜○可★
　金属管工事｜○可★｜○可★
　合成樹脂管工事｜○可★｜○可★
　金属線ぴ工事｜×不可★｜×不可★
　⇒ ケーブル、金属管、合成樹脂管の3つはどこでも可。これを軸に覚える
　⚠ 木造の制限は屋側配線の話。屋内配線では木造でも金属管工事ができる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・出題形式は「点検できない隠ぺい場所であって乾燥した場所の低圧屋内配線の工事方法として、不適切なものはどれか」★
・ひっかけ1：「点検できない隠ぺい場所に金属線ぴ工事を施設した」→×★
・ひっかけ2：「湿気の多い場所にケーブル工事を施設した」→○可
・ひっかけ3：「木造住宅の屋内に金属管工事を施設した」→○可★
・ひっかけ4：「木造住宅の外壁に金属管工事を施設した」→×。屋側では不可★
・ひっかけ5：「使用電圧400Vの屋内配線にライティングダクト工事を施設した」→×。300V超は不可★

★ここだけ暗記
・ケーブル、金属管、合成樹脂管の3つはどこでも施設できる
・線ぴ系とダクト系は乾燥した場所かつ点検できる場所のみ
・木造の制限は屋側配線。屋内配線には及ばない
・300V超では金属線ぴ、ライティングダクト、平形保護層が不可`,
