・クランプメータ：通電したまま負荷電流や漏れ電流を測る★
・検電器：充電の有無を確認する。作業前の安全確認に不可欠★
・回転計や検相器は三相回路の点検で使う
・停電が必要なのは絶縁抵抗計と接地抵抗計と回路計、通電したまま使えるのはクランプメータと検電器、という区別が重要である★

