・ひっかけ3：「100V回路の測定に定格測定電圧1000Vの絶縁抵抗計を用いた」→×。125Vまたは250V★
・ひっかけ4：「測定後に放電せずに端子を外した」→×
・ひっかけ5：「E端子を測定する電線に、L端子を接地極に接続した」→接続が逆。正しくはLが電線

★ここだけ暗記
・定格測定電圧は100V回路125V、200V回路250V、300V超500V
・L端子は電線、E端子は接地極
・必ず停電させ、検電してから測定する
