━━━━━━━━━━━━━━━━━━━━━━
・測定したい電線を1本だけクランプする★
・2本以上を同時にクランプすると、行きと帰りの電流が打ち消し合って値が出ない×★
・単相2線式なら、どちらか1本をクランプすれば負荷電流が読める★
・単相3線式なら、外線1本をクランプすればその線の電流が読める★
・三相3線式なら、各相を1本ずつクランプして3相の電流の平衡を確認する★
・分電盤の主幹や分岐回路の電流を測り、過負荷になっていないかを確認する

━━━━━━━━━━━━━━━━━━━━━━
