━━━━━━━━━━━━━━━━━━━━━━
・その回路のすべての電線をまとめてクランプする★
・単相2線式なら2本、単相3線式なら3本、三相3線式なら3本すべてをまとめる★
・正常なら行きと帰りが打ち消し合ってゼロ、漏電があればその差が表示される★
・漏れ電流の測定には、感度の高い漏れ電流計（リーククランプメータ）を使う★
・絶縁抵抗測定が困難な場合、この方法で漏えい電流1mA以下を確認する★
・接地線をクランプすれば、その接地線を流れる電流が測れる

━━━━━━━━━━━━━━━━━━━━━━
