━━━━━━━━━━━━━━━━━━━━━━
・電線が充電されているかどうか★
・コンセントの接地側極（Wの刻印がある側）と非接地側極の判別★
・接地された白線に検電器を当てても反応しない。黒線に当てれば反応する★
