・三相誘導電動機は、相順が逆になると回転方向が逆になる★
・ポンプやファンを逆回転させると、機器を損傷したり水を送れなかったりする★
・そこで結線後、通電前または通電直後に検相器で相順を確認する★
・回転円板式は円板の回転方向で、ランプ式は点灯するランプで正相か逆相かを判定する★
・第二種の範囲では、名称と用途を知っていれば足りる

━━━━━━━━━━━━━━━━━━━━━━
