・出題形式は「測定器とその用途の組合せとして、誤っているものはどれか」★
・ひっかけ1：「接地抵抗計と絶縁抵抗の測定」→×。接地抵抗の測定★
・ひっかけ2：「クランプメータと絶縁抵抗の測定」→×。電流の測定★
・ひっかけ3：「検相器と電動機の回転速度の測定」→×。相順の確認★
・ひっかけ4：「回路計と導通の確認」→○正しい
・ひっかけ5：「照度計と作業面の明るさの測定」→○正しい★
・ひっかけ6：「検電器と電圧の測定」→×。充電の有無の確認

━━━━━━━━━━━━━━━━━━━━━━
