・照明器具やスイッチへは、壁の中を通して降ろす
・床隠ぺい配線：床下を通す。1階の床下や、2階の床（1階の天井裏）を利用する★
・露出配線：壁の表面にモール（合成樹脂線ぴ）やケーブルを取り付ける★
・改修工事や後付けの配線で使われることが多い
・地中埋設配線：屋外灯や物置への配線。管路式または直接埋設式で施工する★

━━━━━━━━━━━━━━━━━━━━━━
