　配線図は単線図で描かれている。単線図とは、実際には2本や3本の電線が通っている経路を、1本の線で簡略化して描いた図である。図面が見やすくなる代わりに、実際の結線は読み取れない。
　これに対して複線図は、電線を1本ずつすべて描いた図である。どの電線がどの端子につながるかが正確にわかる。実際に配線するときは複線図が必要になる。試験でも技能試験でも、単線図から複線図を起こす力が問われる★

