・ひっかけ1：「単線図から電線の本数が直接読み取れる」→斜線があれば読めるが、問題では省略されている★
・ひっかけ2：「複線図は設計図として使われる」→施工図として使われる
・ひっかけ3：「複線図では電線の色を区別しなくてよい」→×。色の区別が本質★
・ひっかけ4：「技能試験では複線図が問題に示される」→×。単線図だけが示される★
・ひっかけ5：「複線図は必ず定規を使って描く」→×。手描きで十分

