・毎回、①白、②黒、③戻り線の順を崩さないこと★
・描き終わったら、必ず各器具の端子が2つとも埋まっているかを確認する★
・技能試験の候補問題13問を題材にすれば、筆記と技能の対策が同時に進む★
・慣れれば1つの回路を1分程度で描けるようになる

